1	/**
2	 * Money is an integer amount in minor units (cents for USD/EUR) plus an ISO-4217 currency.
3	 * Floating point amounts never enter the domain.
4	 */
5	
6	export interface Money {
7	  readonly amountMinor: number;
8	  readonly currency: string;
9	}
10	
11	/** Number of decimal digits of the minor unit for every currency the service accepts. */
12	const MINOR_UNIT_DIGITS: Readonly<Record<string, number>> = {
13	  USD: 2,
14	  EUR: 2,
15	  GBP: 2,
16	  CAD: 2,
17	  AUD: 2,
18	  MXN: 2,
19	  CHF: 2,
20	  SEK: 2,
21	  JPY: 0,
22	  KRW: 0,
23	};
24	
25	export const SUPPORTED_CURRENCIES: readonly string[] = Object.keys(MINOR_UNIT_DIGITS);
26	
27	export function isSupportedCurrency(code: unknown): code is string {
28	  return typeof code === "string" && Object.hasOwn(MINOR_UNIT_DIGITS, code);
29	}
30	
31	/** True for a non-negative integer that is exactly representable (a valid minor-unit amount). */
32	export function isMinorUnits(value: unknown): value is number {
33	  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
34	}
35	
36	export function minorUnitDigits(currency: string): number {
37	  const digits = MINOR_UNIT_DIGITS[currency];
38	  if (digits === undefined) {
39	    throw new RangeError(`Unsupported currency: ${currency}`);
40	  }
41	  return digits;
42	}
43	
44	export function money(amountMinor: number, currency: string): Money {
45	  if (!isMinorUnits(amountMinor)) {
46	    throw new RangeError(`Amount must be a non-negative integer in minor units, got ${amountMinor}`);
47	  }
48	  if (!isSupportedCurrency(currency)) {
49	    throw new RangeError(`Unsupported currency: ${currency}`);
50	  }
51	  return { amountMinor, currency };
52	}
53	
54	export function zero(currency: string): Money {
55	  return money(0, currency);
56	}
57	
58	export function add(a: Money, b: Money): Money {
59	  assertSameCurrency(a, b);
60	  return money(a.amountMinor + b.amountMinor, a.currency);
61	}
62	
63	export function multiply(m: Money, quantity: number): Money {
64	  if (!Number.isSafeInteger(quantity) || quantity < 0) {
65	    throw new RangeError(`Quantity must be a non-negative integer, got ${quantity}`);
66	  }
67	  return money(m.amountMinor * quantity, m.currency);
68	}
69	
70	export function sum(items: readonly Money[], currency: string): Money {
71	  return items.reduce((total, item) => add(total, item), zero(currency));
72	}
73	
74	function assertSameCurrency(a: Money, b: Money): void {
75	  if (a.currency !== b.currency) {
76	    throw new RangeError(`Currency mismatch: ${a.currency} vs ${b.currency}`);
77	  }
78	}
